import React, { useMemo, useState } from 'react';
import Navbar from '../../components/Navbar/Navbar';
import Footer from '../../components/Footer/Footer';
import styles from './Posts.module.scss';
import { FEED_WEIGHTS } from '../../recommendation/feedConfig';

const PERIODS = [
  'Периодизация',
  'Античност',
  'Средновековие',
  'Ренесанс',
  'Барок',
  'Просвещение',
  'XIX век',
  'Модернизъм',
  'Авангард',
  'Постмодерност',
  'Съвременност'
];

const QUALIFICATION_GROUPS = [
  { name: 'Философия', items: ['История на идеите', 'Етика', 'Метафизика', 'Политическа философия', 'Естетика', 'Други'] },
  { name: 'Литература', items: ['Поезия', 'Проза', 'Драма', 'Есеистика'] },
  { name: 'История', items: ['Политическа история', 'Социална история', 'Културна история', 'Военна история'] },
  { name: 'Изкуства', items: ['Визуални изкуства', 'Музика', 'Театър', 'Кино', 'Архитектура и дизайн', 'Други'] },
  { name: 'Хуманитарни и социални науки', items: ['Антропология', 'Социология', 'Психология', 'Лингвистика', 'Политология'] }
];

const STORAGE_KEY = 'circles-preferences-v1';
const toSpecificKey = (groupName, itemName) => `${groupName}::${itemName}`;

const posts = [
  { id: 1, title: 'Платон и политическата форма', period: 'Античност', general: 'Философия', specific: toSpecificKey('Философия', 'Политическа философия'), author: 'Иван', isFriend: true, isNew: true },
  { id: 2, title: 'Сонети и реторика', period: 'Ренесанс', general: 'Литература', specific: toSpecificKey('Литература', 'Поезия'), author: 'Мария', isFriend: false, isNew: true },
  { id: 3, title: 'Градът като визуален текст', period: 'Модернизъм', general: 'Изкуства', specific: toSpecificKey('Изкуства', 'Архитектура и дизайн'), author: 'Петър', isFriend: true, isNew: false },
  { id: 4, title: 'Етика и общество', period: 'Просвещение', general: 'Философия', specific: toSpecificKey('Философия', 'Етика'), author: 'Никол', isFriend: false, isNew: false },
  { id: 5, title: 'Социални пластове в XIX век', period: 'XIX век', general: 'История', specific: toSpecificKey('История', 'Социална история'), author: 'Георги', isFriend: true, isNew: true },
  { id: 6, title: 'Авангард и киноезик', period: 'Авангард', general: 'Изкуства', specific: toSpecificKey('Изкуства', 'Кино'), author: 'Лора', isFriend: false, isNew: true },
  { id: 7, title: 'Психология на масите', period: 'Съвременност', general: 'Хуманитарни и социални науки', specific: toSpecificKey('Хуманитарни и социални науки', 'Психология'), author: 'Борис', isFriend: false, isNew: false },
  { id: 8, title: 'Средновековна културна карта', period: 'Средновековие', general: 'История', specific: toSpecificKey('История', 'Културна история'), author: 'Елица', isFriend: true, isNew: false },
  { id: 9, title: 'Театърът след постмодерността', period: 'Постмодерност', general: 'Изкуства', specific: toSpecificKey('Изкуства', 'Театър'), author: 'Даниел', isFriend: false, isNew: true },
  { id: 10, title: 'Метафизика и символ', period: 'Барок', general: 'Философия', specific: toSpecificKey('Философия', 'Метафизика'), author: 'Анна', isFriend: true, isNew: false }
];

const loadPreferences = () => {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return { periods: [], generalQualifications: [], specificQualifications: [] };
    const parsed = JSON.parse(raw);
    return {
      periods: Array.isArray(parsed.periods) ? parsed.periods : [],
      generalQualifications: Array.isArray(parsed.generalQualifications) ? parsed.generalQualifications : [],
      specificQualifications: Array.isArray(parsed.specificQualifications) ? parsed.specificQualifications : []
    };
  } catch (error) {
    return { periods: [], generalQualifications: [], specificQualifications: [] };
  }
};

const shuffle = (arr) => [...arr].sort(() => Math.random() - 0.5);

const takeUnique = (source, count, selectedIds) => {
  const result = [];
  for (const item of source) {
    if (result.length >= count) break;
    if (selectedIds.has(item.id)) continue;
    selectedIds.add(item.id);
    result.push(item);
  }
  return result;
};

export default function Posts({ onNavigate }) {
  const initial = useMemo(() => loadPreferences(), []);
  const [selectedPeriods, setSelectedPeriods] = useState(initial.periods);
  const [selectedGeneral, setSelectedGeneral] = useState(initial.generalQualifications);
  const [selectedSpecific, setSelectedSpecific] = useState(initial.specificQualifications);
  const [searchText, setSearchText] = useState('');
  const [message, setMessage] = useState('');

  const toggleValue = (setter, value) => {
    setter((prev) => (prev.includes(value) ? prev.filter((item) => item !== value) : [...prev, value]));
  };

  const toggleGeneral = (groupName) => {
    const group = QUALIFICATION_GROUPS.find((item) => item.name === groupName);
    if (!group) return;

    setSelectedGeneral((prev) => {
      if (!prev.includes(groupName)) return [...prev, groupName];
      setSelectedSpecific((specificPrev) => specificPrev.filter((item) => !item.startsWith(`${groupName}::`)));
      return prev.filter((item) => item !== groupName);
    });
  };

  const toggleSpecific = (groupName, itemName) => {
    toggleValue(setSelectedSpecific, toSpecificKey(groupName, itemName));
    setSelectedGeneral((prev) => (prev.includes(groupName) ? prev : [...prev, groupName]));
  };

  const saveFilters = () => {
    if (selectedGeneral.length === 0) {
      setMessage('Избери поне една обща квалификация.');
      return;
    }

    window.localStorage.setItem(STORAGE_KEY, JSON.stringify({
      periods: selectedPeriods,
      generalQualifications: selectedGeneral,
      specificQualifications: selectedSpecific
    }));
    setMessage('Филтрите са запазени.');
  };

  const feedPosts = useMemo(() => {
    const loweredQuery = searchText.trim().toLowerCase();
    const base = posts.filter((post) => (
      loweredQuery.length === 0 ||
      post.title.toLowerCase().includes(loweredQuery) ||
      post.author.toLowerCase().includes(loweredQuery)
    ));

    const matchesInterest = (post) => {
      const periodOk = selectedPeriods.length === 0 || selectedPeriods.includes(post.period);
      const generalOk = selectedGeneral.length === 0 || selectedGeneral.includes(post.general);
      const specificOk = selectedSpecific.length === 0 || selectedSpecific.includes(post.specific);
      return periodOk && generalOk && specificOk;
    };

    const interestPool = shuffle(base.filter((post) => matchesInterest(post) || post.isFriend));
    const freshPool = shuffle(base.filter((post) => post.isNew));
    const randomPool = shuffle(base);

    const total = Math.min(10, base.length);
    const interestCount = Math.round(total * (FEED_WEIGHTS.interest / 100));
    const freshCount = Math.round(total * (FEED_WEIGHTS.fresh / 100));
    const randomCount = Math.max(0, total - interestCount - freshCount);

    const selectedIds = new Set();
    const first = takeUnique(interestPool, interestCount, selectedIds);
    const second = takeUnique(freshPool, freshCount, selectedIds);
    const third = takeUnique(randomPool, randomCount, selectedIds);

    return [...first, ...second, ...third];
  }, [searchText, selectedPeriods, selectedGeneral, selectedSpecific]);

  return (
    <div className={styles.page}>
      <Navbar currentPage="posts" onNavigate={onNavigate} />
      <main className={styles.main}>
        <section className={styles.header}>
          <h1>Постове</h1>
          <input
            type="text"
            value={searchText}
            onChange={(event) => setSearchText(event.target.value)}
            placeholder="Търси по заглавие или автор"
          />
        </section>

        <section className={styles.layout}>
          <aside className={styles.filters}>
            <h2>Филтър</h2>
            <p className={styles.hint}>Изборите влияят на фийда: {FEED_WEIGHTS.interest}% интереси, {FEED_WEIGHTS.fresh}% нови, {FEED_WEIGHTS.random}% случайни.</p>

            <h3>Периодизация</h3>
            {PERIODS.map((period) => (
              <label key={period} className={styles.option}>
                <input type="checkbox" checked={selectedPeriods.includes(period)} onChange={() => toggleValue(setSelectedPeriods, period)} />
                <span>{period}</span>
              </label>
            ))}

            <h3>Квалификации (общи)</h3>
            {QUALIFICATION_GROUPS.map((group) => (
              <label key={group.name} className={styles.option}>
                <input type="checkbox" checked={selectedGeneral.includes(group.name)} onChange={() => toggleGeneral(group.name)} />
                <span>{group.name}</span>
              </label>
            ))}

            <h3>Квалификации (конкретни)</h3>
            {QUALIFICATION_GROUPS.map((group) => (
              <div key={group.name} className={styles.subgroup}>
                <strong>{group.name}</strong>
                {group.items.map((item) => (
                  <label key={`${group.name}-${item}`} className={styles.option}>
                    <input
                      type="checkbox"
                      checked={selectedSpecific.includes(toSpecificKey(group.name, item))}
                      onChange={() => toggleSpecific(group.name, item)}
                    />
                    <span>{item}</span>
                  </label>
                ))}
              </div>
            ))}

            <button type="button" onClick={saveFilters}>Запази филтър</button>
            {message ? <p className={styles.message}>{message}</p> : null}
          </aside>

          <section className={styles.feed}>
            {feedPosts.length === 0 ? (
              <p className={styles.empty}>Няма резултати за текущия филтър.</p>
            ) : (
              feedPosts.map((post) => (
                <article key={post.id} className={styles.card}>
                  <h3>{post.title}</h3>
                  <p>{post.period} · {post.general}</p>
                  <p>{post.author}{post.isFriend ? ' · приятел' : ''}{post.isNew ? ' · ново' : ''}</p>
                </article>
              ))
            )}
          </section>
        </section>
      </main>
      <Footer />
    </div>
  );
}
